#!/usr/bin/env python3
"""TREE COHORTS (28 Sep, lane N5) · writes ../TREE-COHORTS.html from the three JSON files, so every number on the page is the
number in the file. Plain words; house look; every chart is a saved PNG."""
import json, os, sys, html, collections
import numpy as np
HERE = os.path.dirname(os.path.abspath(__file__)); D = os.path.join(HERE, "..")
ROOT = os.path.abspath(os.path.join(HERE, "../../../.."))
CR = json.load(open(os.path.join(HERE, "critique.json"))); CL = json.load(open(os.path.join(HERE, "clusters.json"))); PR = json.load(open(os.path.join(D, "proposed-cohorts.json")))
CT = json.load(open(os.path.join(ROOT, "deliverables/20260928/coverage-tree/coverage-tree.json")))
COH = {c["key"]: c for c in CT["cohorts"]}
G = json.load(open(sys.argv[1])); GEI = json.load(open(os.path.join(ROOT, "deliverables/20260928/coverage-tree/data/geiger-snapshot-20260928.json")))["symbols"]
def ordn(n): return f"{n}{'th' if 10 <= n % 100 <= 20 else {1: 'st', 2: 'nd', 3: 'rd'}.get(n % 10, 'th')}"
def own_pct(s):
    """today's live reading's place in the fund's replayed 3-year Geiger history, 1..100"""
    v = np.array([x for x in G["symbols"][s]["composite"] if x is not None], dtype=float); t = GEI.get(s, {}).get("composite")
    if t is None or not len(v): return None
    return int(round(100 * (v < t).mean())), t
OP = {s: own_pct(s) for s in ("SPY", "IWM", "MAGS", "QQQ", "RSP", "DIA", "MDY", "IJR")}
e = html.escape
def lab(k): return k.replace("_", " ")
def tbl(head, rows, cls=""):
    return f'<div class="scroll"><table class="{cls}"><tr>' + "".join(f"<th>{h}</th>" for h in head) + "</tr>" + "".join("<tr>" + "".join(f"<td>{c}</td>" for c in r) + "</tr>" for r in rows) + "</table></div>"
def fig_(src, alt):
    return f'<figure><img src="charts/{src}" alt="{e(alt)}"><figcaption><a href="charts/{src}">charts/{src}</a></figcaption></figure>'
def n2(x): return "—" if x is None else f"{x:.2f}"
def pct(x): return "—" if x is None else f"{x:.0%}"

A = PR["admissions"]; T = PR["treatment_counts"]; bf = CR["built_from"]
verd = PR["label_verdicts"]; rep = CL["cohort_reproducibility"]; span = CL["cohort_span"]
attrs = [k for k, v in verd.items() if v["verdict"] == "attribute"]
noparent = CR["no_parent"]
over = CR["overlaps"]
whole = [p for p in over if p["overlap_coef"] == 1.0]
mis = CR["misplaced"]
scout = sorted((t, v) for t, v in PR["treatment"].items() if v["treatment"] == "SCOUT CANDIDATE")
groups = CL["clusters"]
curated = [c for c in PR["cohorts"] if c["kind"] == "curated"]; found = [c for c in PR["cohorts"] if c["kind"] == "group"]; fundc = [c for c in PR["cohorts"] if c["kind"] == "fund"]
adds_theme = [a for a in A["add"] if a["kind"] == "theme"]; adds_need = [a for a in A["add"] if a["kind"].endswith("needs it")]; adds_ok = [a for a in A["add"] if a["kind"].endswith("tracked")]
tabs_today = ["AI_HARDWARE", "AI_SOFTWARE", "MEGACAP", "BLUE_CHIP", "GROWTH", "CRYPTO", "INTL", "MACRO", "INDEXES", "THEMATIC", "METALS", "AI_POWERTRAIN"]
by216 = collections.Counter(r["verdict"] for r in A["rows"])

CSS = """body{margin:0;background:#07070C;color:#B4B4C6;font:17px/1.55 -apple-system,"Helvetica Neue",Arial,sans-serif;padding:28px 40px 80px}
h1{font-size:34px;margin:0 0 6px;color:#C8C8D2}h2{font-size:26px;margin:46px 0 8px;color:#C8C8D2}h3{font-size:19px;margin:26px 0 6px;color:#C8C8D2}
p,li{max-width:1080px}.q{color:#9C9CAE;font-size:13px}
ol.lead{font-size:19px;color:#C8C8D2;max-width:1120px;padding-left:24px}ol.lead li{margin:0 0 12px}
.status{border:1px solid #2A2A36;border-left:4px solid #8A8A9E;padding:12px 16px;margin:18px 0;max-width:1080px;color:#C8C8D2}
code{font:14px ui-monospace,Menlo,monospace;color:#BEBECE}
.scroll{overflow-x:auto;max-width:100%}
table{border-collapse:collapse;font-size:14px;margin:10px 0;font-variant-numeric:tabular-nums}th,td{border:1px solid #24242E;padding:6px 9px;text-align:left;vertical-align:top;max-width:560px}th{color:#A8A8BA;font-weight:600;font-size:13px;font-family:ui-monospace,Menlo,monospace}
table.tight td{font-size:13px}
figure{margin:14px 0;max-width:1500px}figure img{display:block;width:100%;height:auto;background:#0B0B12;border:1px solid #1E1E28}figcaption{color:#9C9CAE;font-size:12px;margin-top:4px;font-family:ui-monospace,Menlo,monospace}
.up{color:#00FFA3}.dn{color:#FF2D55}.rule{border:1px solid #24242E;padding:10px 14px;margin:8px 0;max-width:1080px}.rule b{color:#C8C8D2}.why{color:#9C9CAE;font-size:14px;margin-top:3px}
.tiles{display:flex;gap:14px;flex-wrap:wrap;margin:14px 0}.tile{border:1px solid #24242E;padding:12px 16px;min-width:150px}.tile b{display:block;font-size:30px;color:#C8C8D2;font-variant-numeric:tabular-nums}.tile span{font-size:12px;color:#9C9CAE;font-family:ui-monospace,Menlo,monospace;text-transform:uppercase;letter-spacing:.08em}
dl{max-width:1120px}dt{color:#C8C8D2;font-weight:600;margin-top:12px}dd{margin:2px 0 0 0}
.tag{font:12px ui-monospace,Menlo,monospace;border:1px solid #2A2A36;padding:1px 6px;color:#A8A8BA;margin-left:6px}
.mono{font-family:ui-monospace,Menlo,monospace;font-size:13px}
details{margin:8px 0}summary{cursor:pointer;color:#C8C8D2}
.strip{display:flex;gap:6px;align-items:flex-end;margin:12px 0;max-width:1080px;overflow-x:auto;padding:12px;border:1px solid #24242E}.col{display:flex;flex-direction:column;align-items:center;min-width:64px;font:11px ui-monospace,Menlo,monospace;color:#9C9CAE}.col .bar{width:22px;height:90px;background:#101018;border:1px solid #24242E;position:relative}.col .bar i{position:absolute;left:0;right:0;display:block}.col .bar i.g{background:#00FFA3;bottom:50%}.col .bar i.r{background:#FF2D55;top:50%}.col .bar.h i{background-image:repeating-linear-gradient(45deg,transparent 0 3px,#07070C 3px 5px)}.col .z{position:absolute;left:0;right:0;top:50%;border-top:1px solid #3A3A48}.col b{color:#C8C8D2;font-weight:600;margin-top:4px}
@media(max-width:600px){figure{overflow-x:auto}figure img{min-width:900px}body{padding:20px 16px 60px;font-size:16px}h1{font-size:26px}h2{font-size:22px}ol.lead{font-size:17px}table{font-size:12px}th,td{padding:5px 6px}code{overflow-wrap:anywhere}.tile b{font-size:24px}}"""

out = []
w = out.append
w(f'<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tree cohorts · 28 Sep 2026</title><style>{CSS}</style></head><body>')
w('<span data-scnav-slot></span><h1>The cohorts, rebuilt from the tree down</h1>')
w(f'<div class="q">N5 · 28 Sep 2026 · Fable on Urth · daily Geiger replayed for {bf["symbols_with_history"]} served names over {bf["sessions"]} sessions ({bf["from"]} to {bf["to"]}) · research and a proposal, not a change: nothing was written to the registry, the Hub or the database</div>')
w(f'''<div class="status"><b>STATUS · measured and proposed, nothing changed.</b> Today's 36 cohorts were tested against three years of the Hub's own daily Geiger: how much each cohort's members move together, whether its ETF parent moves with it, how many co-movement groups it spans, and where each name fits best. From that, eight rules and a cohort list of {len(curated)} curated cohorts, {len(found)} groups the data found, {len(fundc)} fund-backed cohorts and {len(PR["fund_cohorts"])} automatic fund cohorts, every one with a parent on the tree. Of the {T["FULL"] + T["SCOUT CANDIDATE"]} FULL names today, {T["SCOUT CANDIDATE"]} are needed by no cohort and no fund read. Of the 216 proposed admissions, {by216["KEEP · FULL"]} earn FULL, {by216["KEEP · SCOUT"]} belong in the scout, {by216["DROP"]} add nothing; {len(adds_theme) + len(adds_need)} names the tree needs are not on the list at all. The INDEX-FUNDS bow-tie tab is designed in section 8. Ten charts saved.</div>''')

# ---------- what this page says
w('<h2>What this page says</h2><ol class="lead">')
w(f'<li><b>Alan was right: the cohorts were made without a tree, and it shows.</b> Seven of 36 have no parent, {len(whole)} pairs are one cohort wholly inside another (METALS and PRECIOUS METALS are the same 17 names), and the three size labels are the market in disguise: LARGE CAP\'s 226 members move together no more than 226 names drawn at random ({verd["LARGE_CAP"]["cohesion"]:.2f} against {verd["LARGE_CAP"]["null95"]:.2f}).</li>')
w(f'<li><b>Real co-movement lives at industry size, about six names, not at cohort size.</b> Splitting the 337 well-served single names into groups and testing whether the two halves of history agree, the agreement keeps rising until about {CL["k_chosen"]} groups. The tightest groups reproduce every time: the ten gold and silver miners (1.00), the eight money-centre banks (0.94), memory and semi equipment (0.92), the nine oil producers (0.82), the seven high-beta small caps (0.80).</li>')
w(f'<li><b>The tree gives every cohort a parent when the parent is chosen by history, not by a holdings share.</b> Rule: the fund whose own Geiger tracked the cohort best over three years, if it beats the sector fund; a cohort of funds hangs under its heading. No cohort is left without a parent.</li>')
w(f'<li><b>Four cohorts should split, six pairs should merge, five labels become filters.</b> AI HARDWARE (43 names in 12 groups) is four cohorts; AI POWER is the generators plus the regulated utilities; BANKS MARKETS is the money-centre banks plus capital markets. LARGE, MEGA, MID and SMALL CAP and BLUE CHIP become cap and style tranches (Alan\'s own statistics dimension), never a bar.</li>')
w(f'<li><b>What goes on the Hub: {T["FULL"]} of today\'s {T["FULL"] + T["SCOUT_CANDIDATE"] if "SCOUT_CANDIDATE" in T else T["FULL"] + T["SCOUT CANDIDATE"]} FULL names are needed by a cohort or a fund read; {T["SCOUT CANDIDATE"]} are not.</b> A name is FULL when it sits in a curated cohort, is a heavy line of a broad or sector fund, or is in a fund\'s smallest tracking set. The rest can be scout names without losing any read. The list is in section 6; nothing moves without Alan.</li>')
w(f'<li><b>The 216 cover the tree, not IWM: only {A["iwm_only"]} of them are IWM-only names and {A["touch_small_or_mid"]} touch IWM, IJR or MDY at all.</b> They are the ten heaviest un-served lines of 36 funds. Re-read against the tree: {by216["KEEP · FULL"]} KEEP as FULL (they complete a cohort or are a heavy line of a fund our names cannot yet track), {by216["KEEP · SCOUT"]} KEEP as scout names, {by216["DROP"]} DROP (they only add weight to funds already tracked at GOOD). And {len(adds_theme)} names that complete a cohort plus {len(adds_need)} heavy lines of under-tracked funds are missing from the list.</li>')
w(f'<li><b>Index funds need their own bow tie and their own scale.</b> An index fund\'s Geiger spends its days in a narrower band than a stock\'s (SPY 5th to 95th point −0.44 to +0.92; single names −0.72 to +0.89, chart 7). The INDEX-FUNDS tab (section 8) shows each fund\'s own bar beside the blend of its served holdings, ordered best to worst, with the count and coverage under every column and the reading\'s place in its own history as the number.</li>')
w('</ol>')

# ---------- 1 · Alan's questions
w('<h2>1 · Alan\'s four questions, answered in plain words</h2><dl>')
w('<dt>"I started the cohorts without a tree, so they are probably weak."</dt><dd>They are, in four measurable ways: no parent (7 of 36), one inside another (' + str(len(whole)) + ' pairs), too broad (three size labels and BLUE CHIP are indistinguishable from random sets; AI HARDWARE spans 12 co-movement groups), and names in the wrong place (section 2 lists ' + str(len(mis)) + ' name-cohort pairs where another cohort\'s mean tracks the name better than its own; the top of that list is NBIS in AI SOFTWARE at 0.15 against 0.75 with the miners and neoclouds).</dd>')
w('<dt>"Expand the logic of cohort creation."</dt><dd>Eight rules in section 4, each with a reason and the number that motivates it. In one line: a cohort is a set of names that move together more than chance, hangs under the tree node whose Geiger moves with it, is split where it contains more than one reproducible group, merged where two labels are one group, and always carries its member count.</dd>')
w(f'<dt>"Determine what goes on the Hub in the new cohorts and what doesn\'t."</dt><dd>Rule R7 and section 6. FULL = in a curated cohort, or a heavy line of a broad or sector fund, or needed to track a fund, or an index or macro fund. Today that keeps {T["FULL"]} names FULL and frees {T["SCOUT CANDIDATE"]}. Fund cohorts (the 49 industry funds) live in the tree with the fund\'s own bar and its holdings bar and need no admission of their own; their un-served names are scout names until Alan promotes one.</dd>')
w(f'<dt>"Do the 216 names cover IWM only or the tree?"</dt><dd>The tree. {A["iwm_only"]} are IWM-only. The list is the ten heaviest un-served lines of each of 36 funds (SPY, QQQ, the iShares and Vanguard sector funds, IBB, XBI, IGV, SMH, SOXX, ITA, IHI, KRE, KBE, IWM, IJR, MDY). Section 7 re-reads every one of them against the tree and adds the {len(adds_theme) + len(adds_need)} names the tree needs that the list does not carry.</dd>')
w('<dt>"What other cohorts do we need?"</dt><dd>The groups the data found that no cohort held: ELECTRIFICATION &amp; MACHINERY (CAT CMI ETN FIX GEV HUBB JCI PH PWR TT URI VRT: the physical AI build-out), HIGH-BETA SMALL CAPS (IONQ QBTS QUBT RGTI ACHR JOBY OKLO: the market trades them as one basket), MONEY-CENTRE BANKS, OIL MAJORS &amp; E&amp;P, REGULATED UTILITIES, PHARMA &amp; BIOTECH, TOWERS, TELECOM, MANAGED CARE, INSURANCE, CAPITAL MARKETS, CHINA, NEOCLOUDS &amp; MINERS, DATA-CENTRE PROPERTY. Most are fund cohorts (rule R8) and cost nothing to keep.</dd></dl>')

# ---------- 2 · critique
w('<h2>2 · How well today\'s tree → cohort mapping works</h2>')
r = CR["registry"]
w(f'<div class="tiles"><div class="tile"><b>{r["distinct_labels"]}</b><span>labels in the registry</span></div><div class="tile"><b>{r["machine_made_labels"]}</b><span>are FMP industry names</span></div><div class="tile"><b>36</b><span>cohort nodes on the tree</span></div><div class="tile"><b>7</b><span>with no parent</span></div><div class="tile"><b>{len(over)}</b><span>overlapping pairs</span></div><div class="tile"><b>{len(whole)}</b><span>one wholly inside another</span></div><div class="tile"><b>{len(r["served_names_in_no_tree_cohort"])}</b><span>served names in no cohort</span></div></div>')
w('<h3>2a · Cohorts with no parent</h3><p>The tree gives a cohort a parent when one fund holds at least a third of its members and those members are at least 1% of the fund. Seven fail. Three are cohorts of funds (INDEXES, MACRO, INTL): no fund holds funds, so they will never have a fund parent; they belong under a heading. Two are not cohorts at all (SMALL CAP, THEMATIC). Two are themes with no fund (CRYPTO, eVTOL).</p>')
w(tbl(["cohort", "why no parent today", "members", "what the proposal does"], [[lab(n["key"]), e(n["reason"] or ""), " ".join(n["members"]), {"CRYPTO": "merged into CRYPTO · EXCHANGES & TREASURIES under the CRYPTO heading", "INTL": "WORLD heading; CHINA split out under MCHI", "THEMATIC": "dissolved into its five themes", "SMALL_CAP": "a cap tranche, not a cohort", "MACRO": "MACRO heading (a watch list, its mean is not shown)", "INDEXES": "US BROAD heading; the INDEX-FUNDS tab", "EVTOL_AUTONOMY": "under the discretionary heading; TSLA listed as a move"}.get(n["key"], "")] for n in noparent]))
w('<h3>2b · Overlapping cohorts</h3>' + fig_("2-overlap.png", "overlap matrix of the 36 cohorts"))
w('<p>Read a row as "how much of this cohort sits inside the column\'s cohort". The pairs that are wholly inside each other:</p>')
PROP = {("METALS", "PRECIOUS_METALS"): "one cohort: METALS · GOLD & SILVER", ("AI_POWERTRAIN", "AI_POWER"): "one cohort: AI POWER (Alan's eight plus ETN, PWR, VRT); the utilities go to XLU", ("AI_HARDWARE", "MEMORY_STORAGE"): "MEMORY & SEMI EQUIPMENT, split out of AI HARDWARE", ("AI_HARDWARE", "AI_DATACENTER"): "NEOCLOUDS & MINERS and DATA-CENTRE PROPERTY, split out", ("AI_HARDWARE", "SEMI_EQUIPMENT"): "MEMORY & SEMI EQUIPMENT", ("LARGE_CAP", "COPPER_STEEL"): "LARGE CAP becomes a cap tranche", ("THEMATIC", "QUANTUM"): "THEMATIC dissolves; QUANTUM stays", ("LARGE_CAP", "CRYPTO"): "LARGE CAP becomes a cap tranche", ("CRYPTO", "CRYPTO_EQUITIES"): "CRYPTO · EXCHANGES & TREASURIES + NEOCLOUDS & MINERS"}
w(tbl(["smaller", "inside", "shared", "of", "proposal"], [[lab(p["a"] if p["n_a"] <= p["n_b"] else p["b"]), lab(p["b"] if p["n_a"] <= p["n_b"] else p["a"]), p["shared"], min(p["n_a"], p["n_b"]), PROP.get((p["a"], p["b"]), PROP.get((p["b"], p["a"]), ""))] for p in whole], "tight"))
w(f'<p>A served name sits in 0 to 5 cohorts (distribution: {", ".join(f"{k} cohorts: {v} names" for k, v in r["tree_cohorts_per_served_name_distribution"].items() if v)}). SMR sits in five (AI POWER, AI POWERTRAIN, MID CAP, NUCLEAR, SOLAR); GEV in four. {len(r["served_names_in_no_tree_cohort"])} served lines sit in no cohort at all, {len([t for t in r["served_names_in_no_tree_cohort"] if t not in CT["coverage"]])} of them companies: {" ".join(t for t in r["served_names_in_no_tree_cohort"] if t not in CT["coverage"])}.</p>')
w('<h3>2c · Too broad, too thin: do the members move together?</h3>' + fig_("1-cohesion.png", "cohesion of each label against random sets"))
w(f'<p>The dot is the mean correlation between the members\' daily Geigers over {bf["sessions"]} sessions; the band is what {300} random sets of the same size give. Below or inside the band the label is not a cohort. LARGE CAP ({verd["LARGE_CAP"]["cohesion"]:.2f} against a band top of {verd["LARGE_CAP"]["null95"]:.2f}), MACRO ({verd["MACRO"]["cohesion"]:.2f}, a deliberate mix of bonds, gold, oil, the dollar and the VIX: a watch list, and its mean bar means nothing) and SOLAR ({verd["SOLAR_RENEWABLE"]["cohesion"]:.2f} with three names) fail. MEGA CAP ({verd["MEGA_CAP"]["cohesion"]:.2f} against {verd["MEGA_CAP"]["null95"]:.2f}) and BLUE CHIP ({verd["BLUE_CHIP"]["cohesion"]:.2f} against {verd["BLUE_CHIP"]["null95"]:.2f}) clear it by a hair: their bar is the market\'s bar (MEGA CAP\'s mean tracks SPY at {CR["cohesion"]["MEGA_CAP"]["mean_vs_spy"]:.2f}). The tightest are the miners, the index funds, quantum, memory, semi equipment and cyber, all above 0.70.</p>')
w(fig_("4-span.png", "share of each cohort in one co-movement group"))
w('<p>The same question from the other side: once the names are grouped by how they actually move (section 3), how much of each cohort lands in one group? Seven cohorts are whole. AI HARDWARE, MID CAP, THEMATIC, AI SOFTWARE, AI ACCELERATORS, AI POWER, MEGACAP PLATFORMS and BANKS MARKETS each span nine or more groups: they are several cohorts wearing one label. This is the measure behind the splits in section 5.</p>')
w(fig_("5-thin.png", "noise of a cohort mean by member count"))
w('<p>Thin is a different problem. A bar built from two names swings twice as much day to day as one built from twenty (0.128 against 0.071). CRYPTO (2 names), CYBER, PHOTONICS and SOLAR (3 each) are pairs, not cohorts; rule R6 says a bar always carries its count and a pair is shown as a pair.</p>')
w('<h3>2d · Does the ETF parent move with its cohort?</h3>' + fig_("6-parent-fit.png", "parent fund fit on history"))
w('<p>Today\'s parent was chosen by holdings share. Measured on three years of history, most parents do move with their cohort (GDX with the miners at 0.98; XLU with AI POWER at 0.94, which is really the utilities inside it; IYG with the banks at 0.93). Four do not beat the sector fund: AI HARDWARE under VGT (0.81, SMH would be 0.94), MID CAP under IWM (0.67, QTUM 0.81: because MID CAP is quantum and eVTOL names), CRYPTO EQUITIES under FINX (0.58) and AI POWERTRAIN under VPU (0.43, URA 0.70). The proposal (rule R1) picks the parent by this number.</p>')
w('<h3>2e · Names in the wrong place</h3><p>For every name, its correlation with its own cohort\'s mean (leave-one-out) against the best other cohort\'s mean. The 30 largest gaps:</p>')
w(tbl(["name", "sits in", "own", "fits better", "corr", "gap", "GICS industry"], [[m["t"], lab(m["cohort"]), n2(m["own"]), lab(m["best_other"]), n2(m["best_other_corr"]), n2(m["gap"]), e(m["gics_industry"] or "")] for m in mis[:30]], "tight"))
w('<p>Most of the top of the list is LARGE CAP and MEGA CAP swallowing energy names (XOM, CVX, SLB, DVN, OXY track the industrial metals better than their size label), memory names that belong with semi equipment (SNDK, WDC), and software that belongs with the security group (SNOW, DDOG, ZS). ETN sits in AI POWER at 0.24 and tracks the accelerators at 0.74: it moves with the data-centre build, not with the utilities. The full list (' + str(len(mis)) + ' rows) is in <code>build/critique.json</code>.</p>')
sm = CR["sector_mismatch"]
w('<p>Names outside their cohort\'s majority sector, by count: ' + ", ".join(f"{lab(k)} {len(v['odd'])} of {v['n']}" for k, v in sorted(sm.items(), key=lambda kv: -len(kv[1]["odd"]))[:10]) + '. For the size labels that is expected; for MEGACAP it is BA and SPCX (industrials) and for AI HARDWARE it is DLR, EQIX, ETN, VRT and WULF.</p>')

# ---------- 3 · co-movement
w('<h2>3 · The co-movement study: how the names really group</h2>')
w(f'<p><b>What was done.</b> The Hub\'s daily-rung Geiger (the same maths as the live <code>/geiger</code>, replayed on the newest 230 daily bars each session) was computed for every served symbol for {bf["sessions"]} sessions. Names were grouped by Ward clustering on 1 − correlation. The number of groups was not chosen by eye (statistician rules R2 and R6): for every count from 4 to 60 the sessions were split into two halves, each half grouped on its own, and the agreement of the two groupings measured (adjusted Rand index, 0 = chance, 1 = identical); the same with odd months against even months. The count reported is the start of the plateau: the smallest count within 0.02 of the best agreement.</p>')
w(fig_("3-stability.png", "stability curve"))
w(f'<p><b>What it says.</b> Agreement rises with the count and flattens around 50: the market\'s co-movement units are industry-sized. At {CL["k_chosen"]} groups the mean group has {337 / CL["k_chosen"]:.1f} names. Shuffled labels give an agreement of {max(n["ari_shuffled_p95"] for n in CL["ari_null"]):.2f}, so every point on the curve is far above chance, but the agreement is far from 1: about a fifth to a third of the pairings hold across halves. Each group below therefore carries a <b>reproducibility</b>: how often its pairs land together across both halves, both month splits and every count from 20 to 60. Background for a random pair: {CL["consensus_background"]["mean"]:.2f}.</p>')
w(f'<p>{len(CL["names_placed_after"])} names with less than a year of readings in one half (new listings and reused tickers) were placed afterwards by nearest group mean and are marked <span class="tag">placed</span>: {", ".join(p["t"] for p in CL["names_placed_after"])}.</p>')
placed = {p["t"] for p in CL["names_placed_after"]}
rows = []
for g in sorted(groups, key=lambda g: -(g["reproducibility"] or 0)):
    ov = ", ".join(f"{lab(k)} {a}/{b}" for k, a, b in g["overlaps_cohorts"][:3]) or "none"
    rows.append([g["cluster"], g["n"], n2(g["reproducibility"]), n2(g["mean_pair_corr"]), " ".join(t + ("*" if t in placed else "") for t in g["members"]), e("; ".join(f"{i[0]} {i[1]}" for i in g["industries"][:2])), ov])
w('<details><summary>The ' + str(len(groups)) + ' groups, most reproducible first (click to open)</summary>' + tbl(["#", "n", "reproducibility", "mean pair corr", "members (* placed)", "GICS industries", "overlaps today's cohorts (held / of)"], rows, "tight") + '</details>')

# ---------- 4 · rules
