for R in PR["rules"]: w(f'<div class="rule"><b>{R["id"]} · {e(R["rule"])}</b><div class="why">Why: {e(R["why"])}</div></div>')

# ---------- 5 · the proposed list
w('<h2>5 · The proposed cohort system</h2>')
w(f'<p>Three kinds. <b>Curated</b> cohorts are Alan\'s themes, re-parented and cleaned ({len(curated)}). <b>Groups the data found</b> are co-movement groups no cohort held ({len(found)}). <b>Fund-backed</b> cohorts are industry groups whose members are what a tree fund holds ({len(fundc)} named here); behind them sit the {len(PR["fund_cohorts"])} automatic fund cohorts of rule R8, one per industry fund on the tree, which need no list. Board tabs are marked; today\'s twelve tabs become {len([c for c in PR["cohorts"] if c["board_tab"]])} plus the INDEX-FUNDS tab.</p>')
w(fig_("9-bowtie-cohorts.png", "proposed cohorts bow tie today"))
def cohort_rows(cs):
    rows = []
    for c in cs:
        g = "; ".join(f"{x['n_here']} in group {x['cluster']} ({n2(x['reproducibility'])})" for x in c["groups"][:3])
        mv = "; ".join(f"{m['t']} → {lab(m['better'])} ({n2(m['own'])} vs {n2(m['better_corr'])})" for m in c["moves"][:4]) or "—"
        rows.append([f"<b>{e(c['label'])}</b>" + (f'<span class="tag">tab {e(c["board_tab"])}</span>' if c["board_tab"] else ""), f"<b>{c['parent']}</b><div class='why'>{e(c['parent_reason'])}</div>", f"{c['n']}", " ".join(c["members"]), " ".join(c["not_served"]) or "—", g, mv, e(c["note"] or "")])
    return tbl(["cohort", "parent on the tree · why", "n", "members (served)", "not served yet", "co-movement groups inside", "moves to consider (own vs better)", "note"], rows, "tight")
w('<h3>5a · Curated cohorts</h3>' + cohort_rows(curated))
w('<h3>5b · Groups the data found</h3>' + cohort_rows(found))
w('<h3>5c · Fund-backed cohorts named here</h3>' + cohort_rows(fundc))
w('<h3>5d · Labels dissolved, merged or turned into filters</h3>' + tbl(["label", "n", "why", "becomes"], [[lab(d["key"]), d["n"], e(d["reason"]), e(d["becomes"])] for d in PR["dissolved"]], "tight"))
w('<h3>5e · The automatic fund cohorts (rule R8)</h3><p>Every industry fund on the tree, with the served holdings that form its cohort, its coverage and whether our names track it. These refresh with the holdings file and are never typed.</p>')
w('<details><summary>' + str(len(PR["fund_cohorts"])) + ' fund cohorts (click to open)</summary>' + tbl(["fund", "label", "sector", "served holdings", "n", "coverage", "tracking", "smallest set that tracks it"], [[f["fund"], e(f["label"]), f["parent"].replace("SEC_", ""), " ".join(f["served_holdings"]), f["n"], pct((f["coverage_pct"] or 0) / 100), e(str(f["tracking"])), " ".join(f["smallest_set"] or []) or "—"] for f in PR["fund_cohorts"]], "tight") + '</details>')

# ---------- 6 · FULL vs scout
w('<h2>6 · What gets the FULL Hub treatment, and what is scout-only</h2>')
w(f'<div class="tiles"><div class="tile"><b>{T["FULL"]}</b><span>FULL · needed</span></div><div class="tile"><b>{T["SCOUT CANDIDATE"]}</b><span>FULL today · needed by nothing</span></div><div class="tile"><b>{T["GEIGER-ONLY"]}</b><span>Geiger-only funds · unchanged</span></div></div>')
w('<p>Rule R7 applied to today\'s served set. A FULL name is kept when at least one of four things is true: it sits in a curated cohort or a data-found group; it is a heavy line of a broad or sector fund (one of the ten heaviest, carrying more than twice an equal-weight share, so equal-weight funds contribute none); it is in a fund\'s smallest tracking set (the names the coverage tree found necessary to read that fund); or it is an index or macro fund on the board. The names that meet none of these are listed below with what still holds them in the tree. Nothing drops by itself: these are candidates for Alan.</p>')
w(tbl(["name", "GICS industry", "cohorts today", "what still holds it"], [[t, e(v.get("gics") or ""), " ".join(lab(k) for k in v.get("cohorts_today", [])) or "—", e(v["why"].split("; ", 1)[1] if "; " in v["why"] else "nothing on the tree")] for t, v in scout], "tight"))
w('<p><b>For new names</b> the door is one-way: a name enters FULL only through the scout page\'s promote mark (the N4 lane) or because a cohort or fund read needs it (section 7). The fund cohorts of rule R8 keep every served holding in the tree whatever its treatment, because the fund\'s own bar is always there.</p>')

